        "alabama": " can’t afford to lose whales by the likes of you; a whale would sell for thirty times what you would, Pip, in Alabama. Bear that in mind, and don’t jump any more.” Hereby perhaps Stubb indirectly hinted, that though man loved his fellow, yet man is a money-making animal, which propensit",
