      "placeQuotes": {
        "nantucket": "The Pequod, of Nantucket, Meets the Samuel Enderby, of London. ”Ship, ahoy! Hast seen the White Whale?” So cried Ahab, once more hailing a ship showing English colours, bearing down under the st",
        "lima": "crown-jewels; as I was groping, I say, after the second iron, to toss it overboard—down comes the tail like a Lima tower, cutting my boat in two, leaving each half in splinters; and, flukes first, the white hump backed through the wreck, as though it was all chips. We all struck out.",
        "manila": ", commanded the ship’s sailors to stand by to lower. In a moment he was standing in the boat’s stern, and the Manilla men were springing to their oars. In vain the English Captain hailed him. With back to the stranger ship, and face set like a flint to his own, Ahab stood upright till a",
        "london": "The Pequod, of Nantucket, Meets the Samuel Enderby, of London. ”Ship, ahoy! Hast seen the White Whale?” So cried Ahab, once more hailing a ship showing English colours, bearing down under the stern. Trumpet to mouth, the old man wa",
        "sri-lanka": " thinks to terrify by feints. But sometimes he is like the old juggling fellow, formerly a patient of mine in Ceylon, that making believe swallow jack-knives, once upon a time let one drop into him in good earnest, and there it stayed for a twelvemonth or more; when I gave him an emeti"
      },
